# port scan plugin
yakit.AutoInitYakit()

/*
本插件定义的函数主要用于端口扫描的额外扩展

函数定义如下：
func(result *fp.MatchResult)

// 详细结构体定义与内容见模版结尾
// 这里最关键的是，如果对扫描出的结果有疑问，需要对 MatchResult 进行修改，应该直接
// 对变量.Field 进行修改。

DEMO:

handle = func(result) {
    if result.Fingerprint != nil {
        if result.Port == 80 && result.GetServiceName() == "" {
            result.Fingerprint.ServiceName = "http"
        }
    }
}

*/

handle = func(result /* *fp.MatchResult */) {
func ParseVersion(version){
    url = "https://docs.microsoft.com/en-us/exchange/new-features/build-numbers-and-release-dates?view=exchserver-2019"
    response ,_= http.Get(url)
	raw, _ := io.ReadAll(response.Body)
	println("[*] Try to access " + url)
	yakit.Info("[*] Try to access " + url)
	//dump(raw)
	pattern_time = re.Find(string(raw),`data-article-date-source="git">(.*?)</time>`)
    println("[+] Article date: " + pattern_time[31:len(pattern_time)-7])
	yakit.Info("[+] Article date: " + pattern_time[31:len(pattern_time)-7])
	tags = re.FindAll(string(raw),`(?is)<tr>(.*?)</tr>`)
	//dump(tags)
	for _,tag = range tags{
		if version in tag{
			println("[+] Exchange Information")
			yakit.Info("[+] Exchange Information")
			//dump(tag)
			tag_infomation = re.FindAll(tag,`(?is)<td(.*?)</td>`)
			for _,versiondata = range tag_infomation{
				if "<a" in versiondata || `style`in versiondata {
					versiondata=re.Find(versiondata,`">(.*?)<`)
					println("    " + versiondata[2:len(versiondata)-1])
					yakit.Info("    " + versiondata[2:len(versiondata)-1])
					}else{
						println("    " + versiondata[4:len(versiondata)-5])
						yakit.Info("    " + versiondata[4:len(versiondata)-5])
					}
				}
			}
		}

	}

func GetVersion(host){
	println("[*] Trying to access EWS")
	yakit.Info("[*] Trying to access EWS")
	url1 = "https://" + string(host) + "/ews"

	req ,_ = http.Get(url1)
	if !("X-Feserver" in req.header) {
		println("[!] Exchange 2010 or older")
		yakit.Info("[!] Exchange 2010 or older")
		println("[*] Trying to access OWA")
		yakit.Info("[*] Trying to access OWA")
		url2 = "https://" + string(host) + "/owa"

		req ,_= http.Get(url2)
		raw, _ := io.ReadAll(req.Body)

		version = re.Find(string(raw),"/owa/(.*?)/themes/resources/favicon.ico")
		version = re.Find(version,`\d+(\.\d+){1,}`)
		println("[+] Version:",version)
		yakit.Info("[+] Version:"+version)

		return version

		}else{
			println("[+] X-Feserver:" + req.header["X-Feserver"][0])
			yakit.Info("[+] X-Feserver:" + req.header["X-Feserver"][0])
			}

	if "X-Owa-Version" in req.header{
		version = req.header["X-Owa-Version"][0]
		println("[+] X-Owa-Version:" + version)
		yakit.Info("[+] X-Owa-Version:" + version)
		return version
		}else{
			println("[!] No X-Owa-Version")
			yakit.Info("[!] No X-Owa-Version")
			println("[*] Trying to access OWA")
			yakit.Info("[*] Trying to access OWA")
			url2 = "https://" + string(host) + "/owa"

			req ,_= http.Get(url2)
			raw, _ := io.ReadAll(req.Body)

			version = re.Find(string(raw),"/owa/(.*?)/themes/resources/favicon.ico")
			version = re.Find(version,`\d+(\.\d+){1,}`)
			println("[+] Version:",version)
			yakit.Info("[+] Version:"+version)

			return version
			}

}
addr = str.HostPort(result.Target, result.Port)
version= GetVersion(addr)
ParseVersion(version)

}

/*
// 具体定义如下：
type palm/common/fp.(MatchResult) struct {
      Target: string  
      Port: int  
      State: fp.PortState  
      Reason: string  
      Fingerprint: *fp.FingerprintInfo  
  StructMethods(结构方法/函数): 
  PtrStructMethods(指针结构方法/函数): 
      func GetBanner() return(string) 
      func GetCPEs() return([]string) 
      func GetDomains() return([]string) 
      func GetHtmlTitle() return(string) 
      func GetProto() return(fp.TransportProto) 
      func GetServiceName() return(string) 
      func IsOpen() return(bool) 
      func String() return(string) 
}


type palm/common/fp.(FingerprintInfo) struct {
      IP: string  
      Port: int  
      Proto: fp.TransportProto  
      ServiceName: string  
      ProductVerbose: string  
      Info: string  
      Version: string  
      Hostname: string  
      OperationVerbose: string  
      DeviceType: string  
      CPEs: []string  
      Raw: string  
      Banner: string  
      CPEFromUrls: map[string][]*webfingerprint.CPE  
      HttpFlows: []*fp.HTTPFlow  
  StructMethods(结构方法/函数): 
  PtrStructMethods(指针结构方法/函数): 
      func FromRegexp2Match(v1: *regexp2.Match) 
}
